import { readFile, stat } from 'node:fs/promises';
import path from 'node:path';
import { zstdDecompressSync } from 'node:zlib';
import { describe, expect, it } from 'vitest';
import { FloatType } from 'three';
import { HDRLoader } from 'three/examples/jsm/loaders/HDRLoader.js';
import { RGBELoader } from 'three-stdlib';
import { read as readKtx2 } from 'ktx-parse';
import { encodeHdr, floatToRgbe } from '../scripts/lib/hdr.mjs';

/**
 * These assets are generated by scripts/, so nothing in code review will
 * catch a broken encoder — a bad RLE run just shows up as a black
 * showroom. Every file is parsed with the loader the browser actually
 * uses, and the RGBE encoder is round-tripped against known values.
 */
const root = path.resolve(import.meta.dirname, '..');
// Copy into a standalone ArrayBuffer: Node's Buffer views a pooled
// allocation, so handing `.buffer` straight to a loader would expose
// neighbouring bytes.
const toArrayBuffer = (buf: Buffer): ArrayBuffer =>
  buf.buffer.slice(
    buf.byteOffset,
    buf.byteOffset + buf.byteLength,
  ) as ArrayBuffer;

const ENVIRONMENTS = ['studio', 'modern-showroom', 'led-studio', 'city-night'];

describe('RGBE encoder', () => {
  it('round-trips a mid-grey through the shared exponent', () => {
    const [r, g, b, e] = floatToRgbe(0.5, 0.5, 0.5);
    const scale = Math.pow(2, e - 128) / 255;
    expect(r * scale).toBeCloseTo(0.5, 2);
    expect(g * scale).toBeCloseTo(0.5, 2);
    expect(b * scale).toBeCloseTo(0.5, 2);
  });

  it('encodes true black as the all-zero pixel', () => {
    expect(floatToRgbe(0, 0, 0)).toEqual([0, 0, 0, 0]);
  });

  it('keeps values above 1.0, which is the whole point of HDR', () => {
    const [r, , , e] = floatToRgbe(14, 14, 14);
    const scale = Math.pow(2, e - 128) / 255;
    expect(r * scale).toBeGreaterThan(10);
  });

  it('survives a round trip through the loader the browser uses', () => {
    // A gradient plus a bright band: the flat run exercises RLE runs, the
    // ramp exercises literal blocks, and the band exercises the HDR range.
    const width = 64;
    const height = 8;
    const data = new Float32Array(width * height * 3);
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const i = (y * width + x) * 3;
        const value = y === 4 ? 12 : x < 32 ? 0.25 : x / width;
        data[i] = value;
        data[i + 1] = value;
        data[i + 2] = value;
      }
    }

    const encoded = encodeHdr(width, height, data);
    const texture = new HDRLoader()
      .setDataType(FloatType)
      .parse(toArrayBuffer(encoded)) as { width: number; height: number; data: Float32Array };

    expect(texture.width).toBe(width);
    expect(texture.height).toBe(height);

    const at = (x: number, y: number) => texture.data[(y * width + x) * 4];
    expect(at(0, 0)).toBeCloseTo(0.25, 2);
    expect(at(10, 2)).toBeCloseTo(0.25, 2);
    expect(at(0, 4)).toBeGreaterThan(10);
    expect(at(48, 1)).toBeCloseTo(48 / width, 1);
  });
});

describe('generated HDR environment maps', () => {
  it.each(ENVIRONMENTS)('%s parses and carries light sources', async (name) => {
    const file = path.join(root, 'public/hdr', `${name}.hdr`);
    const texture = new HDRLoader()
      .setDataType(FloatType)
      .parse(toArrayBuffer(await readFile(file))) as {
      width: number;
      height: number;
      data: Float32Array;
    };

    expect([texture.width, texture.height]).toEqual([1024, 512]);

    let peak = 0;
    let sum = 0;
    for (let i = 0; i < texture.data.length; i += 4) {
      const v = Math.max(
        texture.data[i],
        texture.data[i + 1],
        texture.data[i + 2],
      );
      if (v > peak) peak = v;
      sum += v;
    }
    // A map with nothing above 1.0 has no lights in it and would render
    // the car like a grey box.
    expect(peak).toBeGreaterThan(1);
    // And one that is uniformly bright has lost its contrast.
    expect(sum / (texture.data.length / 4)).toBeLessThan(peak);
  });

  it.each(ENVIRONMENTS)(
    '%s also parses with the loader drei uses',
    async (name) => {
      // drei's <Environment> resolves .hdr through three-stdlib's
      // RGBELoader, which is a separate implementation from three's.
      const file = path.join(root, 'public/hdr', `${name}.hdr`);
      const texture = new RGBELoader().parse(
        toArrayBuffer(await readFile(file)),
      ) as unknown as { width: number; height: number };
      expect([texture.width, texture.height]).toEqual([1024, 512]);
    },
  );
});

describe('generated KTX2 textures', () => {
  it('floor-alpha is a valid container three can read', async () => {
    const file = path.join(root, 'public/textures/floor-alpha.ktx2');
    const container = readKtx2(new Uint8Array(await readFile(file)));

    expect(container.pixelWidth).toBe(512);
    expect(container.pixelHeight).toBe(512);
    // 37 = VK_FORMAT_R8G8B8A8_UNORM. RGBA rather than a single red
    // channel because three samples `.g` for alphaMap and roughnessMap,
    // so a RedFormat texture would read as zero in either slot.
    expect(container.vkFormat).toBe(37);
    expect(container.levels).toHaveLength(1);
  });

  it('inflates to exactly one RGBA byte per pixel channel', async () => {
    const file = path.join(root, 'public/textures/floor-alpha.ktx2');
    const container = readKtx2(new Uint8Array(await readFile(file)));
    const level = container.levels[0];
    // supercompressionScheme 2 = zstd, which three's KTX2Loader inflates.
    expect(container.supercompressionScheme).toBe(2);
    const inflated = zstdDecompressSync(level.levelData);
    expect(inflated.length).toBe(512 * 512 * 4);
    expect(level.uncompressedByteLength).toBe(inflated.length);
  });

  it('is a radial mask: opaque in the middle, transparent at the corners', async () => {
    const file = path.join(root, 'public/textures/floor-alpha.ktx2');
    const container = readKtx2(new Uint8Array(await readFile(file)));
    const px = zstdDecompressSync(container.levels[0].levelData);
    const at = (x: number, y: number) => px[(y * 512 + x) * 4 + 1]; // green
    expect(at(256, 256)).toBe(255);
    expect(at(0, 0)).toBe(0);
    expect(at(511, 511)).toBe(0);
  });

  it('stays small enough to ship', async () => {
    const { size } = await stat(
      path.join(root, 'public/textures/floor-alpha.ktx2'),
    );
    expect(size).toBeLessThan(512 * 1024);
  });
});

describe('vendored Basis transcoder', () => {
  it.each(['basis_transcoder.js', 'basis_transcoder.wasm'])(
    '%s is present, so useKTX2 never reaches for a CDN',
    async (file) => {
      const { size } = await stat(path.join(root, 'public/basis', file));
      expect(size).toBeGreaterThan(1024);
    },
  );
});
